// End-to-end tests: a real VS Code runs the built extension against a scratch workspace
// (out/e2e-workspace, generated by scripts/e2e.mjs) with TLS decryption off, so no root
// certificate has to be trusted on the machine running them.
import { defineConfig } from '@vscode/test-cli'

export default defineConfig({
    files: 'out/e2e/**/*.test.js',
    workspaceFolder: 'out/e2e-workspace',
    version: process.env.VSCODE_VERSION ?? 'stable',
    mocha: { ui: 'tdd', timeout: 90000, color: true },
    launchArgs: ['--disable-extensions', '--disable-workspace-trust'],
    env: { TAPLINE_E2E: '1' }
})
